// ReactionButton.tsx
import { useRef } from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";

gsap.registerPlugin(useGSAP);

export function ReactionButton({ icon, color, onToggle, active, label }) {
  const ref = useRef<HTMLButtonElement>(null);

  const { contextSafe } = useGSAP({ scope: ref });

  const handleClick = contextSafe(() => {
    onToggle?.();
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) return; // state already toggled; skip motion

    const el = ref.current!;
    const iconEl = el.querySelector(".rx-icon");
    gsap.killTweensOf([el, iconEl]); // restart cleanly on spam clicks

    gsap.timeline({ defaults: { overwrite: "auto" } })
      .to(el, { scale: 0.85, duration: 0.08, ease: "power2.out" })
      .to(el, { scale: 1,    duration: 0.42, ease: "back.out(2.4)" })
      .fromTo(iconEl,
        { "--flash": 0 },
        { "--flash": 1, duration: 0.18, ease: "power1.out" }, 0)
      .to(iconEl, { "--flash": 0, duration: 0.25, ease: "power1.in" }, 0.18);
  });

  return (
    <button ref={ref} onClick={handleClick} aria-pressed={active} aria-label={label}
            className="rx-btn" style={{ "--button-color": color } as any}>
      <span className="rx-icon">{icon}</span>
    </button>
  );
}

/* CSS — per-button color is one line at the call site via the `color` prop.
.rx-btn   { background: transparent; border: 0; cursor: pointer; will-change: transform; }
.rx-icon  { color: color-mix(in oklab, currentColor, var(--button-color) calc(var(--flash, 0) * 100%)); display: inline-flex; }
*/

// Usage:
// <ReactionButton color="var(--like-red)"  icon={<HeartIcon/>}  ... />
// <ReactionButton color="var(--gold)"      icon={<BookmarkIcon/>} ... />
// <ReactionButton color="var(--gold-soft)" icon={<ShareIcon/>}  ... />

