"use client";
import { useState, useLayoutEffect, useRef } from "react";
import { gsap } from "gsap";
import { Flip } from "gsap/Flip";
gsap.registerPlugin(Flip);

export function StoryGrid({ stories }: { stories: Story[] }) {
  const [tag, setTag] = useState<string | null>(null);
  const flipState = useRef<Flip.FlipState | null>(null);

  const visible = tag ? stories.filter(s => s.tags.includes(tag)) : stories;

  const onTagClick = (next: string | null) => {
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (!reduce) {
      // Capture BEFORE setState — old DOM is still mounted right now
      flipState.current = Flip.getState(".story-card", { props: "opacity" });
    }
    setTag(next);
  };

  useLayoutEffect(() => {
    if (!flipState.current) return;
    Flip.from(flipState.current, {
      duration: 0.6,
      ease: "power2.inOut",
      absolute: true,            // pin cards during tween — grid won't fight inversions
      stagger: 0.02,
      onEnter: el => gsap.fromTo(el, { opacity: 0, scale: 0.9 }, { opacity: 1, scale: 1, duration: 0.4 }),
      onLeave: el => gsap.to(el, { opacity: 0, scale: 0.9, duration: 0.3 }),
    });
    flipState.current = null;
  }, [tag]);

  return (
    <>
      <TagBar onSelect={onTagClick} />
      <div className="grid grid-cols-3 gap-4">
        {visible.map(s => (
          <article key={s.id} data-flip-id={s.id} className="story-card">{s.title}</article>
        ))}
      </div>
    </>
  );
}
```

